package kingai_test

import("context";"errors";"os";"testing";"time";kingai "github.com/KingOX-cpp/KingAIBrowser/go";"github.com/KingOX-cpp/KingAIBrowser/go/sample")

func connect(t *testing.T)*kingai.Client{t.Helper();path:=os.Getenv("KINGAI_TEST_MCP");if path==""{t.Skip("Test fixture MCP required")};api,err:=kingai.Connect(context.Background(),kingai.Options{MCPExecutable:path,Timeout:3*time.Second});if err!=nil{t.Fatal(err)};t.Cleanup(func(){_ = api.Close()});return api}
func TestSampleUsesRealSDK(t *testing.T){api:=connect(t);ctx:=context.Background();result,err:=sample.RunSample(ctx,api,"sample");if err!=nil{t.Fatal(err)};page:=result.Page.(map[string]any);if page["url"]!="https://example.com"||page["title"]!="Example Domain"{t.Fatalf("unexpected page: %v",page)};trace,err:=api.Call(ctx,"fixture_trace",nil);if err!=nil{t.Fatal(err)};start,evaluate:=0,0;for _,v:=range trace.([]any){if v=="browser_start"{start++};if v=="browser_evaluate"{evaluate++};if v=="browser_close"{t.Fatal("sample must not auto-close browser")}};if start!=1||evaluate!=1{t.Fatalf("calls replayed: start=%d evaluate=%d",start,evaluate)}}
func TestCRUDAndObserve(t *testing.T){api:=connect(t);ctx:=context.Background();p,err:=api.CreateProfile(ctx,"crud",nil);if err!=nil{t.Fatal(err)};id:=p.(map[string]any)["profileId"].(string);if _,err=api.UpdateProfile(ctx,id,kingai.Arguments{"name":"renamed"});err!=nil{t.Fatal(err)};_,err=api.DeleteProfile(ctx,id,false);var apiError *kingai.Error;if !errors.As(err,&apiError)||apiError.Code!="CONFIRMATION_REQUIRED"{t.Fatalf("expected confirmation error, got %v",err)};browser,err:=api.Start(ctx,kingai.Arguments{"profile_id":id});if err!=nil{t.Fatal(err)};_,err=api.UpdateProfile(ctx,id,kingai.Arguments{"name":"busy"});if !errors.As(err,&apiError)||apiError.Code!="SESSION_BUSY"{t.Fatalf("expected busy, got %v",err)};observed,err:=browser.Observe(ctx,"browser_click",kingai.Arguments{"ref":"e1"});if err!=nil{t.Fatal(err)};if observed.(map[string]any)["observationStatus"]!="captured"{t.Fatal(observed)};if _,err=browser.Close(ctx);err!=nil{t.Fatal(err)};if _,err=api.DeleteProfile(ctx,id,true);err!=nil{t.Fatal(err)}}
func TestMalformedResultAndNoReplay(t *testing.T){api:=connect(t);ctx:=context.Background();_,err:=api.Call(ctx,"fixture_bad_response",nil);var apiError *kingai.Error;if !errors.As(err,&apiError)||apiError.Code!="INVALID_TOOL_RESPONSE"{t.Fatal(err)};browser,err:=api.Start(ctx,nil);if err!=nil{t.Fatal(err)};if _,err=api.Call(ctx,"fixture_fail_next",kingai.Arguments{"code":"RESULT_TOO_LARGE"});err!=nil{t.Fatal(err)};_,err=browser.Evaluate(ctx,"document.title");if !errors.As(err,&apiError)||apiError.Code!="RESULT_TOO_LARGE"{t.Fatal(err)};trace,err:=api.Call(ctx,"fixture_trace",nil);if err!=nil{t.Fatal(err)};n:=0;for _,v:=range trace.([]any){if v=="browser_evaluate"{n++}};if n!=1{t.Fatalf("unexpected replay count %d",n)}}
